// Step 7b of DEVDESK-580 (PR2): a fixture that says "flow: bearer" or "flow:
// redirects" holds several exchanges, and the recorder follows them as DevDesk
// would, within limits.
//
// flow: bearer. The first exchange is sent as DevDesk sends it (Basic for admin,
// pull and badcred, nothing for anon). On a 401 whose WWW-Authenticate is a
// Bearer challenge, the recorder follows the challenge only when its realm is
// one of the origins of RecordOptions.Origins (matched on host:port, like the
// Host of a fixture) and the path of the realm is a token path: it sends the
// token request (the identity's Basic, the service and scope of the challenge),
// then the first request again with "Bearer <token>": three exchanges. A realm
// anywhere else ends the flow there: nothing is sent to it, the file holds the
// 401 only and a note, "realm off-origin, not followed". A 401 of the token
// request (the badcred identity) ends it too: two exchanges. No 401 at all: one
// exchange and the note "no challenge". The token read is a term no file and no
// output may hold, whatever the place; an answer that holds it where redaction
// would not show it is a refusal, as for a password.
//
// flow: redirects. A 3xx whose Location is an origin of Origins (and a request
// of the closed list) is followed, up to 5 hops, each one a recorded exchange
// that carries the same credentials as the first; a Location anywhere else is
// recorded and not followed, with the note "off-origin redirect, not followed";
// a chain that goes past 5 hops is an error and nothing is written.
//
// The file keeps its flow header. The note is written in the file; where is the
// recorder's choice. The recorded file is compared with what it holds, all of its
// exchanges, to say "unchanged".
//
// Chosen here, to be confirmed at review: the realm and the Location are matched
// on their host:port against the keys of Origins (the real Nexus names
// 127.0.0.1:30482, the test server listens elsewhere), and the request goes to the
// base URL of that key; a probe host that cannot resolve (realm-probe.invalid) is
// never reached, which a successful run proves.

const (
	recFlowToken   = "REDACTED"
	recRealm       = "http://127.0.0.1:30482/v2/token"
	recNoteRealm   = "realm off-origin, not followed"
	recNoteNoChall = "no challenge"
	recNoteRedir   = "off-origin redirect, not followed"
)

// bearerConfig is what the bench of a Bearer flow does.
type bearerConfig struct {
	token       string
	realm       string // "" = recRealm
	noChallenge bool   // the first request is answered 200
	tokenStatus int    // 0 = 200, or the 401 a wrong password gets
	expiresIn   int    // 0 = 300
	catalog     string // "" = recCatalogBody

// send asks one request of a job, as the credentials of its identity, or with
// bearer as a token when it is not empty, and checks what the bench answers.
func (r *recorder) send(ctx context.Context, j recordJob, rq replayRequest, bearer string) (replayStep, error) {
	c := r.client(j, r.o.Origins[rq.host])
	status, header, body, err := c.recorded(ctx, rq.method, rq.target, rq.header, bearer)
	if err != nil {
		return replayStep{}, recordError("the answer to "+j.name+" could not be read", "check that the bench answers on its loopback ports", err)
	}
	if !benchVersionMatches(header.Get("Server"), r.o.Descriptor) {
		return replayStep{}, recordError("the answer to "+j.name+" does not come from the Nexus version and edition the descriptor names", upCheck, nil)
	}
	if declaresJSON(header.Get("Content-Type")) && len(body) > 0 && !json.Valid(body) {
		return replayStep{}, recordError("the answer to "+j.name+" is declared JSON and is not", "do not record this answer: a secret could hide from the redaction in it", nil)
	}
	return replayStep{raw: nexusfixture.RawExchange{
		Method: rq.method, Target: rq.target, Host: rq.host, RequestHeader: rq.header,
		Status: status, Header: header, Body: body,
	}}, nil
}

// ---- flow: bearer --------------------------------------------------------------------

// bearerChallenge is what a WWW-Authenticate Bearer challenge asks.
type bearerChallenge struct{ realm, service, scope string }

// bearerFlow sends the request, and on a Bearer challenge it can follow, asks for
// the token and sends the request again with it.
func (r *recorder) bearerFlow(ctx context.Context, j recordJob, rq replayRequest) ([]replayStep, string, error) {
	call, err := r.send(ctx, j, rq, "")
	if err != nil {
		return nil, "", err
	}
	steps := []replayStep{call}
	if call.raw.Status != http.StatusUnauthorized {
		return steps, noteNoChallenge, nil
	}
	challenge, ok := parseBearerChallenge(call.raw.Header)
	if !ok {
		return steps, noteNoBearer, nil
	}
	tokenRequest, ok := r.tokenRequest(j, challenge)
	if !ok {
		return steps, noteRealm, nil
	}
	issued, err := r.send(ctx, j, tokenRequest, "")
	if err != nil {
		return nil, "", err
	}
	steps = append(steps, issued)
	if issued.raw.Status != http.StatusOK {
		return steps, noteTokenRefused, nil
	}
	token := tokenOf(issued.raw.Body)
	if token == "" {
		return nil, "", recordError("the token answer to "+j.name+" holds no token", "do not record this answer", nil)
	}
	// Before any check of any answer: the token is a term no file may hold.
	r.terms = append(r.terms, token)
	steps[len(steps)-1].issued = token

	retry := rq
	retry.header = placeholderHeader(rq.header, "Bearer")
	again, err := r.send(ctx, j, retry, token)
	if err != nil {
		return nil, "", err
	}
	return append(steps, again), "", nil
}

