		// ("2Fbench-upstream..."), and decoding can make a match disappear
		// ("nexus.home.arpa%2Dmirror" becomes one longer name, "x.lan%41" too). So the
		// line is scanned decoded and with each escape turned into a separator, and
		// any match of either is a leak.
		texts := []string{percentEscape.ReplaceAllString(line, " ")}
		if decoded, err := url.PathUnescape(line); err == nil && decoded != line {
			texts = append(texts, decoded)
		}
'''
assert a in s
s=s.replace(a,b)
s=s.replace('''	// localPath is a user's home''','''	// percentEscape is a URL escape, a separator for bareHost.
	percentEscape = regexp.MustCompile(`%[0-9A-Fa-f]{2}`)
	// localPath is a user's home''',1)
open(p,'w').write(s)

p='internal/nexusbench/record_flow_test.go'
s=open(p).read()
s=s.replace('''		{"the right origin with user information", "REDACTED", recNoteRealmNF},
''','')
s=s.replace("len(e.rest.requests()); got != 0","len(e.rest.fixtureRequests()); got != 0")
